#include "model.hpp"
#include <QDir>
#include <QFile>
#include <cmath>
#include <QSet>
#include <stdexcept>
static void check(bool yes,const char* why){if(!yes)throw std::runtime_error(why);}
static QString text(const J& j){return j.is_string()?QString::fromStdString(j.get<std::string>()):QString::fromStdString(j.dump());}
static QDomDocument readXml(const QString& path){QFile f(path);check(f.open(QIODevice::ReadOnly),"XML file unavailable");auto b=f.readAll();check(b.size()<131072&&!b.contains("<!DOCTYPE")&&!b.contains("<!ENTITY"),"XML document is not permitted");QDomDocument d;QString error;int row,col;check(d.setContent(b,&error,&row,&col),"Invalid XML");return d;}
static J properties(const QDomElement& root,bool schema){J out=J::object();for(auto p=root.firstChildElement("api").firstChildElement("prop");!p.isNull();p=p.nextSiblingElement("prop")){auto name=p.attribute("name").toStdString();check(!name.empty(),"Binding name required");auto type=p.attribute("type","string");QString value=p.attribute("default");if(schema)out[name]={{"type",type.toStdString()},{"description",p.attribute("description").toStdString()}};else if(type=="number")out[name]=value.toDouble();else out[name]=value.toStdString();}return out;}
Catalog::Catalog(const QString& directory){library=readXml(directory+"/components.xml");for(auto e=library.documentElement().firstChildElement("component");!e.isNull();e=e.nextSiblingElement("component"))components[e.attribute("name")]=e;for(const auto& name:QDir(directory).entryList({"*.xml"},QDir::Files,QDir::Name)){if(name=="components.xml")continue;Screen s;s.xml=readXml(directory+"/"+name);auto root=s.xml.documentElement();check(root.tagName()=="component", "Screen must use LVGL-style component XML");s.id=root.attribute("name");s.title=root.attribute("title");s.question=root.attribute("question");check(!s.id.isEmpty()&&!screens.contains(s.id),"Duplicate/empty template identifier");s.defaults=properties(root,false);s.fields=properties(root,true);check(!root.firstChildElement("view").isNull(),"Screen view required");screens[s.id]=s;}check(screens.size()==10,"The demo requires ten XML screens");}
J Catalog::describe()const{J result=J::array();for(const auto& s:screens)result.push_back({{"id",s.id.toStdString()},{"title",s.title.toStdString()},{"example_question",s.question.toStdString()},{"fields",s.fields},{"sample_defaults",s.defaults}});return result;}
J Catalog::bind(const QString& id,const J& supplied)const{check(screens.contains(id),"Unknown XML template");check(supplied.is_object()&&supplied.dump().size()<32768,"Bound data must be a bounded object");auto data=screens[id].defaults;if(!supplied.empty()){for(const char* field:{"metric1","metric2","metric3","headline1","headline2","headline3"})if(!supplied.contains(field))data[field]="Not supplied";if(!supplied.contains("trend"))data["trend"]="";if(!supplied.contains("summary"))data["summary"]="Muse updated this screen.";if(!supplied.contains("source"))data["source"]="AI content / source not supplied";}for(auto it=supplied.begin();it!=supplied.end();++it){check(data.contains(it.key()),"Unknown template field");if(screens[id].fields[it.key()]["type"]=="number")check(it.value().is_number()&&std::isfinite(it.value().get<double>())&&std::abs(it.value().get<double>())<=1000000,"Invalid numeric field");else check(it.value().is_string()&&it.value().get<std::string>().size()<=4096,"Invalid text field");if(it.key()=="level")check(it.value().get<double>()>=0&&it.value().get<double>()<=100,"Gauge value must be 0 through 100");data[it.key()]=it.value();}return data;}
QDomElement Catalog::expand(QDomDocument& out,const QDomElement& source,const J& data,const QString& inherited,int depth)const{check(depth<12,"XML component nesting too deep");QString engine=source.attribute("engine",inherited);check(engine=="lvgl"||engine=="qt","Layer must select LVGL or Qt");auto substitute=[&](QString value){if(value.startsWith('$')){auto key=value.mid(1).toStdString();check(data.contains(key),"Unbound XML property");return text(data[key]);}return value;};if(source.tagName()=="use"){auto name=source.attribute("component");check(components.contains(name),"Unknown reusable component");auto definition=components[name];auto local=properties(definition,false);auto attrs=source.attributes();for(int i=0;i<attrs.count();i++){auto a=attrs.item(i);if(local.contains(a.nodeName().toStdString())){auto v=substitute(a.nodeValue());if(local[a.nodeName().toStdString()].is_number())local[a.nodeName().toStdString()]=v.toDouble();else local[a.nodeName().toStdString()]=v.toStdString();}}auto node=expand(out,definition.firstChildElement("view"),local,engine,depth+1);for(int i=0;i<attrs.count();i++){auto a=attrs.item(i);if(!local.contains(a.nodeName().toStdString())&&a.nodeName()!="component")node.setAttribute(a.nodeName(),substitute(a.nodeValue()));}return node;}auto tag=source.tagName();if(tag=="view")tag=source.attribute("extends","lv_obj");static const QSet<QString> allowed={"lv_obj","lv_label","lv_button","lv_bar","lv_arc","lv_slider","qt_visual","media_view","media_eq"};check(allowed.contains(tag),"Unsupported widget in shared XML");auto node=out.createElement(tag);node.setAttribute("engine",engine);auto attrs=source.attributes();for(int i=0;i<attrs.count();i++){auto a=attrs.item(i);if(a.nodeName()!="extends")node.setAttribute(a.nodeName(),substitute(a.nodeValue()));}for(auto child=source.firstChildElement();!child.isNull();child=child.nextSiblingElement())node.appendChild(expand(out,child,data,engine,depth+1));return node;}
QDomDocument Catalog::instantiate(const QString& id,const J& supplied)const{auto data=bind(id,supplied);QDomDocument out;auto root=out.createElement("component");out.appendChild(root);auto view=out.createElement("view");view.setAttribute("extends","lv_obj");view.setAttribute("width","1024");view.setAttribute("height","600");view.setAttribute("style_pad_all","0");view.setAttribute("style_border_width","0");view.setAttribute("scrollable","false");view.setAttribute("style_bg_color","0x0c102b");root.appendChild(view);auto input=screens[id].xml.documentElement().firstChildElement("view");for(auto layer=input.firstChildElement("layer");!layer.isNull();layer=layer.nextSiblingElement("layer")){auto engine=layer.attribute("engine");check((engine=="lvgl"&&layer.attribute("z")=="0")||(engine=="qt"&&layer.attribute("z")=="1"),"LVGL layer is z=0 and transparent Qt layer is z=1");for(auto child=layer.firstChildElement();!child.isNull();child=child.nextSiblingElement())view.appendChild(expand(out,child,data,engine,0));}return out;}
QDomDocument Catalog::layer(const QDomDocument& full,const QString& engine){auto out=full.cloneNode(true).toDocument();auto filter=[&](auto&& self,QDomElement parent)->void{for(auto e=parent.firstChildElement();!e.isNull();){auto next=e.nextSiblingElement();if(e.hasAttribute("engine")&&e.attribute("engine")!=engine)parent.removeChild(e);else{e.removeAttribute("engine");e.removeAttribute("action");e.removeAttribute("animation");self(self,e);}e=next;}};filter(filter,out.documentElement());return out;}
